use docconvert::model::*;
#[test]fn meta_defaults(){let m=Meta::default();assert!(m.title.is_none());assert!(m.page_count.is_none());assert!(m.worksheet_count.is_none());assert_eq!(m.source_format,Format::Unknown);assert_eq!(m.source_filename,"");assert_eq!(TableCell::default().colspan,1);assert_eq!(TableCell::default().rowspan,1)}
#[test]fn format_display(){let formats=[Format::Pdf,Format::Docx,Format::Doc,Format::Odt,Format::Ods,Format::Odp,Format::Rtf,Format::Epub,Format::Html,Format::Txt,Format::Markdown,Format::Pptx,Format::Xlsx,Format::Xls,Format::Csv,Format::Tsv,Format::Image,Format::Unknown];let names=["pdf","docx","doc","odt","ods","odp","rtf","epub","html","txt","markdown","pptx","xlsx","xls","csv","tsv","image","unknown"];for(f,n)in formats.iter().zip(names){assert_eq!(f.to_string(),n)}}
#[test]fn nested_inline_text(){let xs=vec![Inline::Styled{style:TextStyle::default(),children:vec![Inline::Link{url:"url".into(),children:vec![Inline::Text("é".into())]}]},Inline::Break,Inline::Code("x".into())];assert_eq!(inline_text(&xs),"é\nx");let mut d=Document::new("x",Format::Txt);d.blocks.push(Block::Paragraph(xs));assert_eq!(d.text_len(),3)}
#[test]fn walker_visits_tables_and_lists(){let mut blocks=vec![Block::Table(Table{header:vec![TableCell{inlines:vec![Inline::Text("a".into())],..TableCell::default()}],..Table::default()}),Block::List{ordered:false,start:None,items:vec![ListItem{level:0,blocks:vec![Block::Paragraph(vec![Inline::Text("b".into())])]}]}];let mut count=0;walk_inlines_mut(&mut blocks,&mut|i|if let Inline::Text(s)=i{count+=1;s.push('!')});assert_eq!(count,2)}
#[test]fn error_categories(){let e=docconvert::error::ConvertError::Unsupported("example".into());assert!(e.is_fatal());assert_eq!(e.to_string(),"unsupported format: example")}
